package com.cpf.starter.notification.dispatch;

import com.cpf.core.api.notification.CpfNotificationRequest;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public final class CpfNotificationPreferencePolicy {private final ConcurrentHashMap<String,Preference> values=new ConcurrentHashMap<>();public void replace(String recipient,Preference p){values.put(recipient,p);}public Decision evaluate(CpfNotificationRequest r,Clock clock){Preference p=values.getOrDefault(r.recipient(),Preference.allowAll());if(!p.channels().contains(r.channel()))return new Decision(false,null,"CHANNEL_DISABLED");ZonedDateTime now=ZonedDateTime.now(clock.withZone(p.zone()));LocalTime time=now.toLocalTime();if(p.quietStart()!=null&&p.quietEnd()!=null&&inQuiet(time,p.quietStart(),p.quietEnd())){ZonedDateTime resume=now.with(p.quietEnd());if(!resume.isAfter(now))resume=resume.plusDays(1);return new Decision(false,resume.toInstant(),"QUIET_HOURS");}return new Decision(true,null,"ALLOWED");}private static boolean inQuiet(LocalTime now,LocalTime start,LocalTime end){return start.isBefore(end)?!now.isBefore(start)&&now.isBefore(end):!now.isBefore(start)||now.isBefore(end);}public record Preference(Set<String> channels,ZoneId zone,LocalTime quietStart,LocalTime quietEnd){public Preference{channels=Set.copyOf(channels);zone=zone==null?ZoneOffset.UTC:zone;}public static Preference allowAll(){return new Preference(Set.of("EMAIL","SMS"),ZoneOffset.UTC,null,null);}}public record Decision(boolean allowed,Instant resumeAt,String reason){} }
